    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    // For a C array DATA_TYPE A[N][N] accessed as A[i][j],
    // use Buffer(N, N) and access as A(j, i).
    Halide::Buffer<num_t, 2> A(n, n);   // dim 0: j (column), dim 1: i (row)

    Halide::Buffer<num_t, 1> u1(n);
    Halide::Buffer<num_t, 1> v1(n);
    Halide::Buffer<num_t, 1> u2(n);
    Halide::Buffer<num_t, 1> v2(n);
    Halide::Buffer<num_t, 1> w(n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);
    Halide::Buffer<num_t, 1> z(n);

    // Initialize data.
    init_array(n, &alpha, &beta,
               A, u1, v1, u2, v2, w, x, y, z);

    // ImageParams for the kernel inputs.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam u1_param(type_of<num_t>(), 1, "u1_param");
    ImageParam v1_param(type_of<num_t>(), 1, "v1_param");
    ImageParam u2_param(type_of<num_t>(), 1, "u2_param");
    ImageParam v2_param(type_of<num_t>(), 1, "v2_param");
    ImageParam w_param(type_of<num_t>(), 1, "w_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");
    ImageParam z_param(type_of<num_t>(), 1, "z_param");

    // Bind ImageParams to Buffers.
    A_param.set(A);
    u1_param.set(u1);
    v1_param.set(v1);
    u2_param.set(u2);
    v2_param.set(v2);
    w_param.set(w);
    x_param.set(x);
    y_param.set(y);
    z_param.set(z);

    // Vars.
    Var i("i"), j("j");

    // Halide translation of kernel_gemver
    //
    // Original C code:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     A[i][j] = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x[i] = x[i] + beta * A[j][i] * y[j];
    //
    // for (i = 0; i < N; i++)
    //   x[i] = x[i] + z[i];
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     w[i] = w[i] + alpha * A[i][j] * x[j];

    // Stage 1: A1(i,j) = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j]
    // Remember: we store A as A(col=j, row=i) = A(j, i).
    Func A1("A1");
    A1(j, i) = A_param(j, i) +
               u1_param(i) * v1_param(j) +
               u2_param(i) * v2_param(j);

    // Stage 2: x1(i) = x[i] + sum_j beta * A[j][i] * y[j]
    // A[j][i] in C corresponds to A1(col=i, row=j) = A1(i, j).
    Func x1("x1");
    x1(i) = x_param(i);
    RDom r_x(0, A_param.dim(1).extent(), "r_x"); // iterate over rows j
    x1(i) += Expr(beta) * A1(i, r_x) * y_param(r_x);

    // Stage 3: x2(i) = x1(i) + z[i]
    Func x2("x2");
    x2(i) = x1(i) + z_param(i);

    // Stage 4: w(i) = w[i] + sum_j alpha * A[i][j] * x[j]
    // A[i][j] in C corresponds to A1(col=j, row=i) = A1(j, i).
    Func w_func("w_func");
    w_func(i) = w_param(i);
    RDom r_w(0, A_param.dim(0).extent(), "r_w"); // iterate over columns j
    w_func(i) += Expr(alpha) * A1(r_w, i) * x2(r_w);

    // Simple schedule: rely on Halide's default. No explicit reordering needed.

    // JIT-compile the pipeline.
    w_func.compile_jit();

    // Time the kernel execution (excluding compilation).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize result into w (overwriting initial w).
    w_func.realize(w);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results to prevent dead-code elimination, similar to PolyBench's print_array.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << w(idx) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
