#include "defines.hpp"

// include benchmark-specific definitions
#include "gemver.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays using Halide Funcs, mirroring the original C init_array.
 *
 * Original C:
 *
 *   *alpha = 1.5;
 *   *beta  = 1.2;
 *   fn = (DATA_TYPE)n;
 *   for i:
 *     u1[i] = i;
 *     u2[i] = ((i+1)/fn)/2.0;
 *     v1[i] = ((i+1)/fn)/4.0;
 *     v2[i] = ((i+1)/fn)/6.0;
 *     y[i]  = ((i+1)/fn)/8.0;
 *     z[i]  = ((i+1)/fn)/9.0;
 *     x[i]  = 0.0;
 *     w[i]  = 0.0;
 *     for j:
 *       A[i][j] = (DATA_TYPE)(i*j % n) / n;
 *
 * Mapping to Halide:
 *   - 1D arrays: Buffer<num_t, 1>, indexed as buf(i).
 *   - 2D A[i][j] -> Buffer<num_t, 2> A(j, i) (rule 1).
 */
static void init_array(int n,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,   // shape (n, n), A(j, i) == C's A[i][j]
                       Halide::Buffer<num_t, 1> u1,
                       Halide::Buffer<num_t, 1> v1,
                       Halide::Buffer<num_t, 1> u2,
                       Halide::Buffer<num_t, 1> v2,
                       Halide::Buffer<num_t, 1> w,
                       Halide::Buffer<num_t, 1> x,
                       Halide::Buffer<num_t, 1> y,
                       Halide::Buffer<num_t, 1> z) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // fn = (DATA_TYPE)n;
    Expr fn = Expr((num_t)n);

    Func init_u1("init_u1"), init_u2("init_u2");
    Func init_v1("init_v1"), init_v2("init_v2");
    Func init_y("init_y"), init_z("init_z");
    Func init_x("init_x"), init_w("init_w");
    Func init_A("init_A");

    // u1[i] = i;
    init_u1(i) = Expr((num_t)i);

    // u2[i] = ((i+1)/fn)/2.0;
    init_u2(i) = (Expr((num_t)(i + 1)) / fn) / Expr((num_t)2.0);

    // v1[i] = ((i+1)/fn)/4.0;
    init_v1(i) = (Expr((num_t)(i + 1)) / fn) / Expr((num_t)4.0);

    // v2[i] = ((i+1)/fn)/6.0;
    init_v2(i) = (Expr((num_t)(i + 1)) / fn) / Expr((num_t)6.0);

    // y[i] = ((i+1)/fn)/8.0;
    init_y(i) = (Expr((num_t)(i + 1)) / fn) / Expr((num_t)8.0);

    // z[i] = ((i+1)/fn)/9.0;
    init_z(i) = (Expr((num_t)(i + 1)) / fn) / Expr((num_t)9.0);

    // x[i] = 0.0;
    init_x(i) = Expr((num_t)0.0);

    // w[i] = 0.0;
    init_w(i) = Expr((num_t)0.0);

    // A[i][j] = (DATA_TYPE)(i*j % n) / n;
    // C row-major A[i][j] -> Buffer A(j, i) per rule 1.
    init_A(j, i) = Expr((num_t)((i * j) % n)) / fn;

    // Realize into the provided buffers.
    init_u1.realize(u1);
    init_u2.realize(u2);
    init_v1.realize(v1);
    init_v2.realize(v2);
    init_y.realize(y);
    init_z.realize(z);
    init_x.realize(x);
    init_w.realize(w);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // For A[N][N] accessed as A[i][j], we use shape (n, n) and map A(i,j_C) as A(j, i).
    Halide::Buffer<num_t, 2> A(n, n); // x: j, y: i

    Halide::Buffer<num_t, 1> u1(n);
    Halide::Buffer<num_t, 1> v1(n);
    Halide::Buffer<num_t, 1> u2(n);
    Halide::Buffer<num_t, 1> v2(n);
    Halide::Buffer<num_t, 1> w(n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);
    Halide::Buffer<num_t, 1> z(n);

    // Initialize data
    init_array(n, &alpha, &beta,
               A, u1, v1, u2, v2, w, x, y, z);

    // ImageParams to feed into the Halide kernel
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam u1_param(type_of<num_t>(), 1, "u1_param");
    ImageParam v1_param(type_of<num_t>(), 1, "v1_param");
    ImageParam u2_param(type_of<num_t>(), 1, "u2_param");
    ImageParam v2_param(type_of<num_t>(), 1, "v2_param");
    ImageParam w_param(type_of<num_t>(), 1, "w_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");
    ImageParam z_param(type_of<num_t>(), 1, "z_param");

    // Bind buffers to ImageParams
    A_param.set(A);
    u1_param.set(u1);
    v1_param.set(v1);
    u2_param.set(u2);
    v2_param.set(v2);
    w_param.set(w);
    x_param.set(x);
    y_param.set(y);
    z_param.set(z);

    // Vars
    Var i("i"), j("j");

    // RDom over j (0..n-1) for reductions
    RDom r1(0, A.dim(0).extent(), "r1"); // used for x update (sum over rows j)
    RDom r2(0, A.dim(0).extent(), "r2"); // used for w update (sum over columns j)

    // Stage 1: rank-2 update of A
    // for (i) for (j)
    //   A[i][j] = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
    //
    // We produce a new Func A1(j, i) corresponding to updated A[i][j].
    Func A1("A1");
    A1(j, i) = A_param(j, i) +
               u1_param(i) * v1_param(j) +
               u2_param(i) * v2_param(j);

    // Stage 2: x[i] = x[i] + beta * A[j][i] * y[j];
    // Note: C's A[j][i] (row j, col i) -> A1(col = i, row = j) -> A1(i, j).
    Func x1("x1");
    x1(i) = x_param(i);
    x1(i) += Expr(beta) * A1(i, r1) * y_param(r1);

    // Stage 3: x[i] = x[i] + z[i];
    Func x2("x2");
    x2(i) = x1(i) + z_param(i);

    // Stage 4: w[i] = w[i] + alpha * A[i][j] * x[j];
    // C's A[i][j] (row i, col j) -> A1(col = j, row = i) -> A1(j, i).
    Func w_out("w_out");
    w_out(i) = w_param(i);
    w_out(i) += Expr(alpha) * A1(r2, i) * x2(r2);

    // (Optional) simple root-level scheduling; default loop order already
    // matches the original for-loop structure reasonably well.
    A1.compute_root();
    x1.compute_root();
    x2.compute_root();
    w_out.compute_root();

    // JIT-compile the kernel
    w_out.compile_jit();

    // Timing
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: compute w_out into w
    w_out.realize(w);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print result (to avoid dead-code elimination and for checking)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << w(idx) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
