#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (e.g., N, DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions
#include "gemver.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the arrays, following the original C init_array() logic,
 * but expressed using small Halide pipelines.
 *
 * C-side semantics:
 *
 *   *alpha = 1.5;
 *   *beta  = 1.2;
 *
 *   fn = (DATA_TYPE)n;
 *   for i in [0..n-1]:
 *     u1[i] = i;
 *     u2[i] = ((i+1)/fn)/2.0;
 *     v1[i] = ((i+1)/fn)/4.0;
 *     v2[i] = ((i+1)/fn)/6.0;
 *     y[i]  = ((i+1)/fn)/8.0;
 *     z[i]  = ((i+1)/fn)/9.0;
 *     x[i]  = 0.0;
 *     w[i]  = 0.0;
 *     for j in [0..n-1]:
 *       A[i][j] = (DATA_TYPE)(i*j % n) / n;
 *
 * Mapping to Halide:
 *   - 2D C array A[i][j] (row-major) is mapped to Buffer A(j, i)
 *     with shape (n, n): dim 0 = j (columns), dim 1 = i (rows).
 *   - 1D arrays are mapped directly: u1(i), v1(i), etc.
 */
static void init_array(int n,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 1> u1,
                       Halide::Buffer<num_t, 1> v1,
                       Halide::Buffer<num_t, 1> u2,
                       Halide::Buffer<num_t, 1> v2,
                       Halide::Buffer<num_t, 1> w,
                       Halide::Buffer<num_t, 1> x,
                       Halide::Buffer<num_t, 1> y,
                       Halide::Buffer<num_t, 1> z) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A");
    Func init_u1("init_u1"), init_u2("init_u2");
    Func init_v1("init_v1"), init_v2("init_v2");
    Func init_w("init_w"), init_x("init_x");
    Func init_y("init_y"), init_z("init_z");

    // fn = (DATA_TYPE)n;
    Expr fn = cast<num_t>(n);
    Expr base = cast<num_t>(i + 1) / fn;

    // 1D initializations
    init_u1(i) = cast<num_t>(i);
    init_u2(i) = base / Expr((num_t)2.0);
    init_v1(i) = base / Expr((num_t)4.0);
    init_v2(i) = base / Expr((num_t)6.0);
    init_y(i)  = base / Expr((num_t)8.0);
    init_z(i)  = base / Expr((num_t)9.0);

    init_x(i) = cast<num_t>(0);
    init_w(i) = cast<num_t>(0);

    // 2D initialization:
    // A[i][j] = (DATA_TYPE)(i*j % n) / n;
    // Map to A(j, i) with shape (n, n).
    init_A(j, i) = cast<num_t>((i * j) % n) / cast<int>(n);

    // Realize into the provided buffers
    init_A.realize(A);
    init_u1.realize(u1);
    init_u2.realize(u2);
    init_v1.realize(v1);
    init_v2.realize(v2);
    init_w.realize(w);
    init_x.realize(x);
    init_y.realize(y);
    init_z.realize(z);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A: C uses A[N][N] with A[i][j].
    //    We store as A_buf(j, i) with shape (n, n) (cols, rows).
    Halide::Buffer<num_t, 2> A_buf(n, n);

    // 1D vectors of length n.
    Halide::Buffer<num_t, 1> u1_buf(n), v1_buf(n);
    Halide::Buffer<num_t, 1> u2_buf(n), v2_buf(n);
    Halide::Buffer<num_t, 1> w_buf(n), x_buf(n);
    Halide::Buffer<num_t, 1> y_buf(n), z_buf(n);

    // Initialize data
    init_array(n, &alpha, &beta,
               A_buf,
               u1_buf, v1_buf,
               u2_buf, v2_buf,
               w_buf, x_buf,
               y_buf, z_buf);

    // Wrap the buffers as ImageParams for use in the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam u1_param(type_of<num_t>(), 1, "u1_param");
    ImageParam v1_param(type_of<num_t>(), 1, "v1_param");
    ImageParam u2_param(type_of<num_t>(), 1, "u2_param");
    ImageParam v2_param(type_of<num_t>(), 1, "v2_param");
    ImageParam w0_param(type_of<num_t>(), 1, "w0_param");
    ImageParam x0_param(type_of<num_t>(), 1, "x0_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");
    ImageParam z_param(type_of<num_t>(), 1, "z_param");

    A_param.set(A_buf);
    u1_param.set(u1_buf);
    v1_param.set(v1_buf);
    u2_param.set(u2_buf);
    v2_param.set(v2_buf);
    w0_param.set(w_buf);
    x0_param.set(x_buf);
    y_param.set(y_buf);
    z_param.set(z_buf);

    // ------------------------------------------------------------------
    // Halide translation of kernel_gemver
    //
    // Original C kernel:
    //
    // 1) for i, j: A[i][j] += u1[i]*v1[j] + u2[i]*v2[j];
    // 2) for i, j: x[i] += beta * A[j][i] * y[j];
    // 3) for i:    x[i] += z[i];
    // 4) for i, j: w[i] += alpha * A[i][j] * x[j];
    //
    // We express this in a functional style:
    //
    //   A1[i][j] = A0[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
    //
    //   x(i) = x0(i);
    //   x(i) += beta * sum_j A1[j][i] * y[j];  // using updated A
    //   x(i) += z[i];
    //
    //   w(i) = w0(i);
    //   w(i) += alpha * sum_j A1[i][j] * x[j];
    //
    // Note: A0 is A_param, A1 is a Func; x0, w0 are x0_param, w0_param.
    // ------------------------------------------------------------------

    Var i("i"), j("j");
    Func A1("A1"), x_func("x_func"), w_func("w_func");

    // A1(j, i) corresponds to A1[i][j] in C.
    A1(j, i) = A_param(j, i)
               + u1_param(i) * v1_param(j)
               + u2_param(i) * v2_param(j);

    // x(i): starts from x0(i), then two update definitions.
    x_func(i) = x0_param(i);

    // First update: x[i] += beta * A1[j][i] * y[j] (C: A[j][i])
    // Mapping:
    //   C: A1[j][i] -> Halide: A1(x = i, y = j) == A1(i, r)
    RDom r1(0, n, "r1");
    x_func(i) += Expr(beta) * A1(i, r1) * y_param(r1);

    // Second update: x[i] += z[i];
    x_func(i) += z_param(i);

    // w(i): starts from w0(i), then one reduction.
    w_func(i) = w0_param(i);

    // w[i] += alpha * A1[i][j] * x[j]
    // Mapping:
    //   C: A1[i][j] -> Halide: A1(x = j, y = i) == A1(r2, i)
    RDom r2(0, n, "r2");
    w_func(i) += Expr(alpha) * A1(r2, i) * x_func(r2);

    // A simple schedule that respects the dataflow:
    //
    // - Let x_func and w_func compute at root.
    // - A1 will be inlined by default (no explicit schedule needed).
    x_func.compute_root();
    w_func.compute_root();

    // Optionally, we can reorder the reduction loops to match the C
    // traversal order (i outer, j/r inner), though this is also the
    // default for 1D reductions.
    x_func.update(0).reorder(i, r1);       // x += beta * ...
    x_func.update(1).reorder(i);           // x += z
    w_func.update().reorder(i, r2);        // w += alpha * ...

    // Compile the pipeline to machine code once.
    w_func.compile_jit();

    // Measure execution time of the Halide kernel.
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into w_buf (overwriting initial contents).
    w_func.realize(w_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting w for debugging / DCE prevention,
    // similar to the PolyBench print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; ++idx) {
            std::cerr << w_buf(idx) << '\n';
        }
    }

    // Print the elapsed time (in seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
