    //
    // for (i)
    //   x[i] += z[i];
    //
    // for (i)
    //   for (j)
    //     w[i] += alpha * A[i][j] * x[j];
    //
    // Note that x and w are initialized to zero in init_array.
    // We compute the final w as a pure functional pipeline:
    //   A_updated, x1, x2, w_out.
    // ----------------------------------------------------------------

    Var i("i"), j("j");

