    Var i("i"), j("j");
    // We use the runtime size of A's dimensions for reduction bounds.
    RDom r_y(0, A.dim(1).extent(), "r_y"); // rows (original i/j as needed)
    RDom r_x(0, A.dim(0).extent(), "r_x"); // cols

    // Halide pipeline corresponding to kernel_gemver.
    //
    // Original C kernel:
    //
    // for i,j: A[i][j] = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
    // for i,j: x[i]    = x[i] + beta * A[j][i] * y[j];
    // for i:   x[i]    = x[i] + z[i];
    // for i,j: w[i]    = w[i] + alpha * A[i][j] * x[j];
    //
    // Mapping: A[i][j] <-> A_param(j, i).

    Func A1("A1");   // Updated A after the rank-1 updates.
    Func x1("x1");   // After accumulation over j.
    Func x2("x2");   // After adding z.
    Func w1("w1");   // Final w.

    // First loop: update A.
    // A1(j, i) = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
    A1(j, i) = A_param(j, i)
             + u1_param(i) * v1_param(j)
             + u2_param(i) * v2_param(j);

    // Second loop: x accumulation over j (row index).
    // x[i] = x[i] + beta * A[j][i] * y[j];
    // A[j][i] in C corresponds to A1(i, j) in Halide.
    x1(i) = x_param(i);
    x1(i) += Expr(beta) * A1(i, r_y) * y_param(r_y);

    // Third loop: add z.
    // x[i] = x[i] + z[i];
    x2(i) = x1(i) + z_param(i);

